// ---- Calculate Stage 2 Score ----
// The AI only gives 0-5 scores with evidence. The math (questionnaire score + combined score) is done here in code.
const cfg = {};
for (const i of $('Read Config (Stage 2)').all()) { const k = String(i.json.key || '').trim(); if (k) cfg[k] = i.json.value; }
const v = $('Validate Stage 2 Link').first().json;
const answers = $('Prepare Stage 2 Answers').first().json._answers;
const req = $('Build Stage 2 AI Request').first().json;
const max = Number(cfg.score_scale_max) || 5;
const resp = $input.first().json;

// 1) Read the AI answer safely
const content = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
if (!content) throw new Error('AI returned no content: ' + JSON.stringify(resp).slice(0, 400));
let ai;
try { ai = JSON.parse(String(content).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '')); }
catch (e) { throw new Error('AI response was not valid JSON: ' + String(content).slice(0, 300)); }

const byId = {};
for (const x of (ai.answers || [])) byId[String(x.question_id || '').trim()] = x;
const notScored = v.questions.filter(q => !byId[q.question_id]).map(q => q.question_id);
if (notScored.length) throw new Error('AI did not score these questions: ' + notScored.join(', '));

// 2) Score each question + evidence check against THAT answer
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const totalWeight = v.questions.reduce((s, q) => s + q.weight, 0) || 100;
const results = [];
const extraConcerns = [];
let points = 0;
for (const q of v.questions) {
  const a = byId[q.question_id];
  const ansNorm = norm((answers.find(x => x.question_id === q.question_id) || {}).answer);
  let score = Math.round(Number(a.score));
  if (isNaN(score)) score = 0;
  score = Math.max(0, Math.min(max, score));
  const evidence = String(a.evidence || '').trim();
  const noEvidence = !evidence || /no evidence/i.test(evidence);
  const found = s => ansNorm.includes(s.slice(0, 40)) ||
    s.split(/[,;]/).map(x => x.trim()).filter(x => x.length > 2).every(x => ansNorm.includes(x.slice(0, 40)));
  const quotes = noEvidence ? [] : evidence.split('|').map(s => norm(s).replace(/^["'“]|["'”]$/g, '')).filter(Boolean);
  const verified = noEvidence ? true : quotes.every(found);
  if (score > 0 && noEvidence) extraConcerns.push(`${q.question_id} scored ${score} without evidence - please verify`);
  if (!verified) extraConcerns.push(`${q.question_id} evidence quote not found word-for-word in the answer - please verify`);
  const weighted = (score / max) * q.weight;
  points += weighted;
  results.push({ question_id: q.question_id, question: q.question, score, max_score: max, weight: q.weight,
    evidence: evidence || 'No evidence in answer', evidence_verified: verified, reason: String(a.reason || '').trim() });
}
const stage2Score = Math.round((points / totalWeight) * 100 * 10) / 10;

// 3) Combined score = resume and questionnaire, weighted by Config (normalized)
const wr = Number(cfg.stage2_weight_resume);
const wq = Number(cfg.stage2_weight_questionnaire);
const wR = isNaN(wr) ? 60 : wr, wQ = isNaN(wq) ? 40 : wq;
const resume = Number(v.resume_score);
const hasResume = String(v.resume_score ?? '').trim() !== '' && !isNaN(resume);
const combined = hasResume && (wR + wQ) > 0 ? Math.round(((resume * wR + stage2Score * wQ) / (wR + wQ)) * 10) / 10 : '';
const shortlistAt = Number(cfg.shortlist_threshold) || 75;
const reviewAt = Number(cfg.review_threshold) || 50;
const bandOf = n => n === '' ? '' : n >= shortlistAt ? 'Shortlist' : n >= reviewAt ? 'Review' : 'Low match';

const list = x => (Array.isArray(x) ? x : (x ? [x] : [])).map(s => String(s).trim()).filter(Boolean);
const strengths = list(ai.strengths);
const concerns = [...list(ai.concerns).filter(c => !/^(there are )?no (significant |major |real )?concerns/i.test(c)), ...extraConcerns];
// Only claims the resume does not support become flags; 'supported' and 'modest' claims are fine
const flags = (Array.isArray(ai.claim_checks) ? ai.claim_checks : [])
  .filter(x => x && ['not_in_resume', 'exceeds_resume'].includes(String(x.type || '').trim().toLowerCase()))
  .map(x => `${x.question_id || ''} claims ${String(x.claim || '').trim()}; resume shows ${String(x.resume_shows || '').trim()}`.trim())
  .concat(list(ai.consistency_flags));
const breakdown = results.map(x => `${x.question_id} ${x.score}/${max}`).join(' | ');
const stamp = $now.setZone('Asia/Manila').toFormat('yyyy-MM-dd HH:mm:ss');

return [{
  json: {
    candidate_id: v.candidate_id,
    stage2_score: String(stage2Score),
    combined_score: String(combined),
    stage2_summary: [String(ai.summary || ''), 'Scores: ' + breakdown,
      flags.length ? 'CHECK CLAIMS: ' + flags.join('; ') : '',
      strengths.length ? 'Strengths: ' + strengths.join('; ') : '', concerns.length ? 'Concerns: ' + concerns.join('; ') : ''].filter(Boolean).join('\n'),
    stage2_scores_json: JSON.stringify(results),
    last_updated: stamp,
    // context for the email + audit steps (ignored by the sheet)
    _results: results, _summary: String(ai.summary || ''), _strengths: strengths, _concerns: concerns, _flags: flags,
    _breakdown: breakdown, _stage2_band: bandOf(stage2Score), _combined_band: bandOf(combined),
    _weights: `${wR}/${wQ}`, _model: req.model, _tokens: resp.usage ? (resp.usage.total_tokens || '') : ''
  }
}];

