// Free interview slots = working hours on allowed weekdays, minus lunch/break, minus busy calendar time (+ buffer),
// minus anything sooner than the minimum notice. All times in Philippine Time.
const cfg = {};
for (const i of $('Read Config (Interview)').all()) { const k = String(i.json.key || '').trim(); if (k) cfg[k] = i.json.value; }
const v = $('Validate Interview Link').first().json;
const Z = 'Asia/Manila';
const now = $now.setZone(Z);

const minutes = v.minutes;
const buffer = Number(cfg.interview_buffer_minutes) || 0;
const aheadDays = Number(cfg.interview_days_ahead) || 5;
const noticeH = Number(cfg.interview_min_notice_hours) || 12;
const hm = (s, d) => { const m = String(s || d).trim().match(/^(\d{1,2}):(\d{2})/); return m ? { hour: +m[1], minute: +m[2] } : null; };
const dayStart = hm(cfg.interview_day_start, '09:00');
const dayEnd = hm(cfg.interview_day_end, '17:00');
const brk = String(cfg.interview_break || '').split('-').map(x => hm(x, '')).filter(Boolean);
const DAYS = { mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6, sun: 7 };
const allowed = String(cfg.interview_weekdays || 'Mon,Tue,Wed,Thu,Fri').split(',').map(x => DAYS[x.trim().slice(0, 3).toLowerCase()]).filter(Boolean);
if (!dayStart || !dayEnd) throw new Error('Config interview_day_start / interview_day_end must look like 09:00 and 17:00.');

// Busy blocks from Google Calendar (items with start/end), widened by the buffer
const busy = $input.all().map(i => i.json).filter(b => b && b.start && b.end).map(b => ({
  s: DateTime.fromISO(String(b.start)).setZone(Z).minus({ minutes: buffer }),
  e: DateTime.fromISO(String(b.end)).setZone(Z).plus({ minutes: buffer })
}));
const overlaps = (s, e, list) => list.some(b => s < b.e && e > b.s);

const earliest = now.plus({ hours: noticeH });
const slots = [];
let day = now.startOf('day');
let workDays = 0;
for (let n = 0; n < 31 && workDays < aheadDays; n++, day = day.plus({ days: 1 })) {
  if (!allowed.includes(day.weekday)) continue;
  const open = day.set(dayStart), close = day.set(dayEnd);
  if (close <= earliest) continue;                     // whole day too soon - does not count
  workDays++;
  const blocked = brk.length === 2 ? [{ s: day.set(brk[0]), e: day.set(brk[1]) }] : [];
  for (let t = open; t.plus({ minutes }) <= close; t = t.plus({ minutes: 30 })) {
    const e = t.plus({ minutes });
    if (t < earliest || overlaps(t, e, blocked) || overlaps(t, e, busy)) continue;
    slots.push({ label: t.toFormat('ccc, LLL d') + ' - ' + t.toFormat('h:mm a'), start: t.toISO(), end: e.toISO(),
      start_text: t.toFormat('yyyy-MM-dd HH:mm'), end_text: e.toFormat('yyyy-MM-dd HH:mm') });
  }
}

