const b = $('Prepare Booking Row').first().json;
let sheetUrl = '';
try { sheetUrl = String($('SETUP - Paste Your Sheet URL').params.assignments.assignments.find(a => a.name === 'sheet_url').value || ''); } catch (e) { sheetUrl = ''; }
const esc = x => String(x === undefined || x === null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const claims = (String(v.stage2_summary || '').split('\n').find(l => /^CHECK CLAIMS:/i.test(l)) || '').replace(/^CHECK CLAIMS:\s*/i, '');
const verify = claims
  ? `<p style="background:#fdecea;padding:8px 12px;border-left:4px solid #c0392b"><b>Verify in the interview (from Stage 2):</b><br>${claims.split('; ').map(esc).join('<br>')}</p>` : '';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.55;color:#1f2933;max-width:640px">
  <h2 style="margin:0 0 4px">Interview booked: ${esc(v.full_name)}</h2>
  <p style="margin:0 0 12px">${esc(v.email)} | ${esc(v.job_title)}</p>
  <p style="font-size:16px"><b>${esc(b._label)}</b> (Philippine Time), ${esc(v.minutes)} minutes<br>
  Google Meet: ${b.interview_meet_link ? `<a href="${esc(b.interview_meet_link)}">${esc(b.interview_meet_link)}</a>` : 'see the calendar event'}
  ${b._event_link ? `<br><a href="${esc(b._event_link)}">Open calendar event</a>` : ''}</p>
  <table style="border-collapse:collapse;margin:0 0 12px">
    <tr><td style="padding:3px 14px 3px 0">Resume score</td><td><b>${esc(v.resume_score)}/100</b></td></tr>
    <tr><td style="padding:3px 14px 3px 0">Questionnaire score</td><td><b>${esc(v.stage2_score || '-')}/100</b></td></tr>
    <tr><td style="padding:3px 14px 3px 0">Combined score</td><td><b>${esc(v.combined_score || '-')}/100</b></td></tr>
  </table>
  ${verify}
  <p><a href="${esc(v.resume_drive_link)}">Open resume (PDF)</a>${sheetUrl ? ` &nbsp;|&nbsp; <a href="${esc(sheetUrl)}">Open Candidates sheet</a>` : ''}</p>
  <p style="font-size:12px;color:#6b7785">Booked by the candidate via their personal link. The candidate received the Google Calendar invitation. Candidate ID: ${esc(v.candidate_id)} | Execution ${esc($execution.id)}</p></div>`;
const stamp = $now.setZone('Asia/Manila').toFormat('yyyy-MM-dd HH:mm:ss');
const id = $now.setZone('Asia/Manila').toFormat('yyyyMMddHHmmss');
return [{ json: {
  to: cfg.recruiter_email,
  subject: `${claims ? '[CHECK CLAIMS] ' : ''}[Interview booked] ${v.full_name} - ${b._label} - ${v.job_title}`,
  html,
  _audit: [
    { log_id: v.candidate_id + '-IV-BOOKED-' + id, timestamp: stamp, candidate_id: v.candidate_id, email: v.email, actor: 'candidate',
      event_type: 'INTERVIEW_BOOKED', details: 'Interview booked for ' + b.interview_start + ' to ' + b.interview_end + ' (Asia/Manila) | event ' + b.interview_event_id + ' | Meet ' + (b.interview_meet_link || 'n/a'),
      workflow_version: cfg.workflow_version || 'v1.0', execution_id: $execution.id },
    { log_id: v.candidate_id + '-IV-NOTIFIED-' + id, timestamp: stamp, candidate_id: v.candidate_id, email: v.email, actor: 'system',
      event_type: 'RECRUITER_NOTIFIED', details: 'Interview booking emailed to ' + (cfg.recruiter_email || ''),
      workflow_version: cfg.workflow_version || 'v1.0', execution_id: $execution.id }
  ]
} }];
